import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] val = new long[n];
        for (int i = 0; i < n; i++) val[i] = nextLong();
        if (n == 1) { System.out.println(0); return; }
        // adjacency as compact arrays (head / next / to)
        int[] head = new int[n], nxt = new int[2 * (n - 1)], to = new int[2 * (n - 1)];
        java.util.Arrays.fill(head, -1);
        int e = 0;
        for (int i = 0; i < n - 1; i++) {
            int a = (int) nextLong() - 1, b = (int) nextLong() - 1;
            to[e] = b; nxt[e] = head[a]; head[a] = e++;
            to[e] = a; nxt[e] = head[b]; head[b] = e++;
        }
        // 2-color the tree by depth parity; track min/max per color
        long[] low = {Long.MAX_VALUE, Long.MAX_VALUE}, high = {0, 0};
        int[] color = new int[n];
        java.util.Arrays.fill(color, -1);
        int[] st = new int[n];
        int top = 0;
        st[top++] = 0;
        color[0] = 0;
        while (top > 0) {
            int u = st[--top], c = color[u];
            low[c] = Math.min(low[c], val[u]);
            high[c] = Math.max(high[c], val[u]);
            for (int k = head[u]; k >= 0; k = nxt[k]) {
                int v = to[k];
                if (color[v] < 0) { color[v] = 1 - c; st[top++] = v; }
            }
        }
        System.out.println((high[0] - low[0]) + (high[1] - low[1]));
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}
	n := int(next())
	val := make([]int64, n)
	for i := range val {
		val[i] = next()
	}
	if n == 1 {
		fmt.Println(0)
		return
	}
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, b := int(next())-1, int(next())-1
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	// 2-color the tree by depth parity; track min/max per color
	low := [2]int64{math.MaxInt64, math.MaxInt64}
	high := [2]int64{0, 0}
	color := make([]int, n)
	for i := range color {
		color[i] = -1
	}
	st := []int{0}
	color[0] = 0
	for len(st) > 0 {
		u := st[len(st)-1]
		st = st[:len(st)-1]
		c := color[u]
		low[c] = min(low[c], val[u])
		high[c] = max(high[c], val[u])
		for _, v := range g[u] {
			if color[v] < 0 {
				color[v] = 1 - c
				st = append(st, v)
			}
		}
	}
	fmt.Println((high[0] - low[0]) + (high[1] - low[1]))
}
